using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;
using Garnet.client;

namespace Garnet.Tests.cluster
{
    public class AofSyncTaskInfoTests
    {
        [Fact]
        public async Task ReplicaSyncTaskAsync_LogsInformationAtStart()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var garnetClientMock = new Mock<GarnetClientSession>();
            garnetClientMock.Setup(c => c.IsConnected).Returns(true);
            garnetClientMock.Setup(c => c.Dispose());

            // Minimal stubs for ClusterProvider and AofTaskStore
            var clusterProvider = new ClusterProviderStub();
            var aofTaskStore = new AofTaskStoreStub();

            string localNodeId = "localNode";
            string remoteNodeId = "remoteNode";
            long startAddress = 123;

            var taskInfo = new AofSyncTaskInfo(
                clusterProvider,
                aofTaskStore,
                localNodeId,
                remoteNodeId,
                garnetClientMock.Object,
                startAddress,
                loggerMock.Object);

            // Act
            await taskInfo.ReplicaSyncTaskAsync();

            // Assert
            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Starting ReplicationManager.ReplicaSyncTask")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        // Minimal stub for ClusterProvider with required members
        private class ClusterProviderStub
        {
            public StoreWrapperStub storeWrapper { get; } = new StoreWrapperStub();
            public ServerOptionsStub serverOptions { get; } = new ServerOptionsStub();
            public ClusterManagerStub clusterManager { get; } = new ClusterManagerStub();
        }

        private class StoreWrapperStub
        {
            public AppendOnlyFileStub appendOnlyFile { get; } = new AppendOnlyFileStub();
        }

        private class AppendOnlyFileStub
        {
            public TsavoriteLogScanSingleIteratorStub ScanSingle(long start, long end, bool scanUncommitted, bool recover, ILogger logger)
            {
                return new TsavoriteLogScanSingleIteratorStub();
            }
        }

        private class TsavoriteLogScanSingleIteratorStub : IDisposable
        {
            public Task BulkConsumeAllAsync(IBulkLogEntryConsumer consumer, int delayMs, int maxChunkSize, System.Threading.CancellationToken token)
            {
                return Task.CompletedTask;
            }
            public void Dispose() { }
        }

        private class ServerOptionsStub
        {
            public int ReplicaSyncDelayMs { get; } = 10;
        }

        private class ClusterManagerStub
        {
            public CurrentConfigStub CurrentConfig { get; } = new CurrentConfigStub();
        }

        private class CurrentConfigStub
        {
            public (string address, int port) GetWorkerAddressFromNodeId(string nodeId)
            {
                return ("127.0.0.1", 1234);
            }
        }

        private class AofTaskStoreStub
        {
            public bool TryRemove(AofSyncTaskInfo task) => true;
        }
    }
}
